// And groups predicates with the AND operator between them.
func And(predicates ...predicate.DebtDetails) predicate.DebtDetails {
	return predicate.DebtDetails(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.DebtDetails) predicate.DebtDetails {
	return predicate.DebtDetails(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.DebtDetails) predicate.DebtDetails {
	return predicate.DebtDetails(sql.NotPredicates(p))
}
